/* Tabler dashboard views; all data is a local synthetic simulation. */
(()=>{'use strict';
const H=window.Hayat,D=window.HayatData,{$,$$,safe:e,icon:i,url}=H;
const role=document.body.dataset.page,view=document.body.dataset.view||'dashboard';
let user,state,page=1,query='',filter='',bankFilter='',dateFrom='',dateTo='',sort='newest';
const secondaryPages=new Map();
const names={donor:'مساحة المتبرع',bank:'مساحة المؤسسة',admin:'إدارة النظام'},statusNames={active:'نشط',fulfilled:'مستوفى',cancelled:'ملغي',confirmed:'مؤكد',corrected:'مصحح',accepted:'مقبول',declined:'اعتذر',withdrawn:'تم التراجع',coordinating:'بانتظار التنسيق',pending_activation:'بانتظار التفعيل',pending_verification:'بانتظار التفعيل',suspended:'موقوف',pending:'بانتظار الرد',unread:'غير مقروء',read:'مقروء'};
const menu={donor:[['dashboard','layout-dashboard','نظرة عامة'],['notifications','bell','الطلبات والإشعارات'],['eligibility','heart-check','التوفر والأهلية الأولية'],['history','history','سجل التبرعات'],['points','award','نقاط العطاء'],['profile','user-circle','الملف الشخصي']],bank:[['dashboard','layout-dashboard','نظرة عامة'],['requests','clipboard-list','إدارة الطلبات'],['create-request','circle-plus','إنشاء طلب دم'],['donors','user-search','البحث عن متبرع'],['record-donation','droplet-check','توثيق تبرع'],['reports','report-analytics','تقارير المؤسسة'],['staff','users-group','إدارة الموظفين'],['profile','user-circle','الملف الشخصي']],admin:[['dashboard','layout-dashboard','نظرة عامة'],['users','users','المستخدمون'],['blood-banks','building-hospital','بنوك الدم'],['requests','clipboard-list','متابعة الطلبات'],['donations','droplet-check','سجلات التبرع'],['points','receipt','النقاط والتدقيق'],['health-reports','report-medical','الإشراف الصحي'],['profile','user-circle','الملف الشخصي']]};
const link=(v,params='')=>url(`${role}/${v}.html${params}`),bank=id=>state.banks.find(b=>b.id===id),person=id=>H.allUsers().find(u=>u.id===id),date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('ar-PS',{year:'numeric',month:'short',day:'numeric'}):'—';
const badge=(s)=>`<span class="badge bg-${['active','confirmed','accepted','fulfilled'].includes(s)?'teal':['cancelled','suspended','corrected','declined'].includes(s)?'red':'yellow'}-lt">${e(statusNames[s]||s)}</span>`;
const blood=g=>`<span class="blood-type">${e(g==='unknown'?'غير معروفة':g)}</span>`;
const urgency=u=>`<span class="badge bg-${u==='normal'?'blue':u==='critical'?'red':'orange'}-lt">${u==='critical'?'حرج':['urgent','high'].includes(u)?'عاجل':'اعتيادي'}</span>`;
const empty=(title='لا توجد نتائج',desc='جرّب تعديل البحث أو الفلاتر.',action='')=>`<div class="empty"><div class="empty-icon">${i('inbox')}</div><p class="empty-title">${title}</p><p class="empty-subtitle text-secondary">${desc}</p>${action?`<div class="empty-action">${action}</div>`:''}</div>`;
const medical=`<div class="medical-note mt-4">${i('stethoscope')} الترشيح والتوقيت للتنسيق الأولي فقط. الأهلية النهائية والفحوصات والتوافق الطبي مسؤولية المؤسسة المختصة.</div>`;
const button=(text,ic,attrs='',style='primary')=>`<button class="btn btn-${style}" type="button" ${attrs}>${i(ic)} ${text}</button>`;
const field=(name,label,type='text',value='',extra='')=>`<div class="mb-3"><label class="form-label" for="${name}">${label}</label><input class="form-control" id="${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}><span class="field-error" data-error-for="${name}"></span></div>`;
const select=(name,label,options,value='',extra='')=>`<div class="mb-3"><label class="form-label" for="${name}">${label}</label><select class="form-select" name="${name}" id="${name}" ${extra}>${options.map(([v,t])=>`<option value="${e(v)}" ${v===value?'selected':''}>${e(t)}</option>`).join('')}</select></div>`;
const groupOptions=D.groups.map(g=>[g,g]);
const formWrap=(id,title,content,submit='حفظ التغييرات')=>`<div class="card dashboard-form"><div class="card-header"><h2 class="card-title">${title}</h2></div><div class="card-body"><div class="form-alert" id="form-alert" role="alert"></div><form id="${id}">${content}<div class="border-top pt-3 mt-3 d-flex flex-wrap gap-2"><button class="btn btn-primary" type="submit">${i('check')} ${submit}</button><a class="btn btn-outline-secondary" href="${link('dashboard')}">العودة للوحة</a></div></form></div></div>`;
function scopedDonations(){return state.donations.filter(d=>role==='admin'||(role==='bank'?d.bankId===user.bankId:d.donorId===user.id))}
function scopedRequests(){const commitment=role==='donor'?D.activeCommitment(user.id,state):null;return state.requests.filter(r=>role==='admin'||(role==='bank'?r.bankId===user.bankId:commitment?r.id===commitment.requestId:D.matches(user,r,state)||state.notifications.some(n=>n.donorId===user.id&&n.requestId===r.id)||state.donor_responses.some(response=>response.donorId===user.id&&response.requestId===r.id)))}
function responseFor(r){return state.donor_responses.find(x=>x.requestId===r.id&&x.donorId===user.id)}
function responseBadge(response){return response.status==='accepted'?`${badge('accepted')} ${response.releasedAt?'<span class="badge bg-secondary-lt">انتهى التنسيق</span>':badge('coordinating')}`:badge(response.status)}
function withdrawButton(requestId){return button('التراجع عن الاستجابة','arrow-back-up',`data-withdraw data-id="${requestId}"`,'outline-danger')}
function commitmentPanel(){
 const response=D.activeCommitment(user.id,state);if(!response)return '';
 const request=state.requests.find(r=>r.id===response.requestId),institution=bank(request.bankId);
 return `<section class="card mb-4" data-active-commitment="${e(request.id)}" aria-labelledby="current-coordination-title"><div class="card-body"><div class="d-flex gap-3 align-items-start"><span class="avatar bg-teal-lt">${i('circle-check')}</span><div class="flex-fill"><h2 class="h3 mb-2" id="current-coordination-title">استجابتك مسجلة · بانتظار التنسيق</h2><p class="mb-1"><strong>${e(institution?.name)}</strong> · ${blood(request.bloodType)} · ${e(institution?.city)}، ${e(institution?.area)}</p><p class="text-secondary small mb-3">النداءات الأخرى مخفية مؤقتًا أثناء تنسيقك لهذا الطلب. يمكنك التراجع إذا لم تعد قادرًا على الاستجابة.</p><div class="d-flex flex-wrap gap-2"><a class="btn btn-primary" href="${link('request-details','?id='+encodeURIComponent(request.id))}">متابعة طلبي ${i('arrow-left')}</a>${withdrawButton(request.id)}</div></div></div></div></section>`;
}
function donorRequestActions(request){
 const response=responseFor(request);
 if(response?.status==='accepted'&&!response.releasedAt)return `<div class="text-teal w-100" role="status">${i('circle-check')} استجابتك مسجلة، بانتظار تنسيق المؤسسة. النداءات الأخرى مخفية مؤقتًا.</div>${withdrawButton(request.id)}`;
 if(response?.releaseReason==='donation_confirmed')return `<p class="text-secondary mb-0">انتهى تنسيقك لهذا الطلب بعد توثيق التبرع. يمكنك متابعة السجل وحركات النقاط.</p><a class="btn btn-outline-secondary" href="${link('history')}">سجل التبرعات</a>`;
 if(request.status!=='active'||!D.matches(user,request,state))return '<span class="text-secondary small">الطلب مغلق أو خارج الترشيح الحالي.</span>';
 if(response?.status==='declined')return `<span class="text-secondary w-100">اعتذرت عن هذا الطلب. يمكنك تغيير استجابتك إذا أصبحت متاحًا.</span>${button('أستطيع الاستجابة الآن','check',`data-respond="accepted" data-id="${request.id}"`)}`;
 return `${response?.status==='withdrawn'?'<span class="text-secondary w-100">تراجعت عن استجابتك السابقة.</span>':''}${button('أستطيع الاستجابة','check',`data-respond="accepted" data-id="${request.id}"`)}${button('أعتذر عن الطلب','x',`data-respond="declined" data-id="${request.id}"`,'outline-secondary')}`;
}
function filterData(rows,getText,{ignoreStatus=false}={}){return rows.filter(r=>(!query||getText(r).toLowerCase().includes(query.toLowerCase()))&&(!filter||ignoreStatus||r.status===filter)&&(!bankFilter||r.bankId===bankFilter)&&(!dateFrom||(r.donatedAt||r.at||r.createdAt||'').slice(0,10)>=dateFrom)&&(!dateTo||(r.donatedAt||r.at||r.createdAt||'').slice(0,10)<=dateTo))}
function table(headers,rows,row,{key='main',caption=''}={}){
 if(!rows.length)return empty();
 const max=Math.ceil(rows.length/8),current=Math.max(1,Math.min(key==='main'?page:(secondaryPages.get(key)||1),max));
 if(key==='main')page=current;else secondaryPages.set(key,current);
 rows=[...rows].sort((a,b)=>sort==='name'?String(a.name||a.reference||a.id).localeCompare(String(b.name||b.reference||b.id),'ar'):String(a.at||a.createdAt||a.donatedAt||a.id).localeCompare(String(b.at||b.createdAt||b.donatedAt||b.id))*(sort==='oldest'?1:-1));
 const start=(current-1)*8;
 return `<p class="d-md-none text-secondary small px-3 py-2 mb-0">${i('arrows-horizontal')} اسحب الجدول لعرض باقي الأعمدة.</p><div class="table-responsive" tabindex="0" role="region" aria-label="${e(caption||'جدول السجلات')}، قابل للتمرير أفقيًا"><table id="table-${key}" class="table table-vcenter card-table">${caption?`<caption class="visually-hidden">${e(caption)}</caption>`:''}<thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.slice(start,start+8).map(row).join('')}</tbody></table></div><div class="card-footer d-flex flex-wrap gap-2 align-items-center justify-content-between"><span class="text-secondary small" role="status">عرض ${start+1}–${Math.min(start+8,rows.length)} من ${rows.length}</span><div class="btn-list" aria-label="صفحات ${e(caption||'السجلات')}">${button('السابق','chevron-right',`data-page="${current-1}" data-page-key="${key}" ${current===1?'disabled':''}`,'outline-secondary')}${button('التالي','chevron-left',`data-page="${current+1}" data-page-key="${key}" ${current===max?'disabled':''}`,'outline-secondary')}</div></div>`;
}
function toolbar({statuses=[],banks=false,dates=false,exportable=false}={}){return `<div class="data-toolbar"><input class="form-control" id="table-search" type="search" placeholder="ابحث في السجلات…" aria-label="البحث في السجلات" value="${e(query)}"><select class="form-select" id="table-sort" aria-label="ترتيب السجلات"><option value="newest" ${sort==='newest'?'selected':''}>الأحدث أولًا</option><option value="oldest" ${sort==='oldest'?'selected':''}>الأقدم أولًا</option><option value="name" ${sort==='name'?'selected':''}>الاسم أو المرجع</option></select>${statuses.length?`<select class="form-select" id="status-filter" aria-label="تصفية الحالة"><option value="">كل الحالات</option>${statuses.map(s=>`<option value="${s}" ${filter===s?'selected':''}>${statusNames[s]}</option>`).join('')}</select>`:''}${banks?`<select class="form-select" id="bank-filter" aria-label="تصفية المؤسسة"><option value="">كل المؤسسات</option>${state.banks.map(b=>`<option value="${b.id}" ${bankFilter===b.id?'selected':''}>${e(b.name)}</option>`).join('')}</select>`:''}${dates?`<input class="form-control" style="max-width:170px" type="date" id="date-from" aria-label="من تاريخ" value="${e(dateFrom)}"><input class="form-control" style="max-width:170px" type="date" id="date-to" aria-label="إلى تاريخ" value="${e(dateTo)}">`:''}${exportable?button('تصدير CSV','download','data-export','outline-secondary'):''}</div>`}
function shell(){const active=view==='request-details'?(role==='donor'?'notifications':'requests'):view;const nav=menu[role].filter(([v])=>v!=='staff'||user.staffType==='representative');const title=view==='request-details'?'تفاصيل طلب الدم':menu[role].find(([v])=>v===active)?.[2]||'تفاصيل الطلب';
 $('#app').innerHTML=`<aside class="navbar navbar-vertical navbar-expand-lg dashboard-sidebar" aria-label="التنقل في ${names[role]}"><div class="container-fluid">${H.brand()}<button class="navbar-toggler ms-auto" type="button" data-bs-toggle="offcanvas" data-bs-target="#sidebar-menu" aria-controls="sidebar-menu" aria-expanded="false" aria-label="فتح قائمة اللوحة"><span class="navbar-toggler-icon"></span></button><div class="offcanvas-lg offcanvas-start navbar-collapse" id="sidebar-menu" tabindex="-1" aria-labelledby="sidebar-title"><div class="offcanvas-header d-lg-none"><h2 class="h3 mb-0" id="sidebar-title">قائمة حياة</h2><button type="button" class="btn-close" data-bs-dismiss="offcanvas" data-bs-target="#sidebar-menu" aria-label="إغلاق القائمة"></button></div><div class="offcanvas-body"><div class="sidebar-label">${names[role]}</div><ul class="navbar-nav">${nav.map(([v,ic,t])=>`<li class="nav-item"><a class="nav-link ${v===active?'active':''}" ${v===active?'aria-current="page"':''} href="${link(v)}"><span class="nav-link-icon">${i(ic)}</span><span class="nav-link-title">${t}</span></a></li>`).join('')}</ul><div class="sidebar-bottom"><div class="small text-secondary mb-2">${role==='bank'?e(bank(user.bankId)?.name||'المؤسسة'):'عطاؤك حياة'}</div><a class="btn btn-ghost-secondary w-100 justify-content-start mb-2" href="${url('index.html')}">${i('world')} الموقع الرئيسي</a>${button('تسجيل الخروج','logout','data-logout','outline-secondary')}${role==='admin'?`<button class="btn btn-ghost-danger w-100 mt-2" type="button" data-reset>${i('refresh')} إعادة ضبط التجربة</button>`:''}</div></div></div></div></aside><div class="page-wrapper"><div class="demo-strip">نسخة تجريبية · بيانات افتراضية محفوظة في هذا المتصفح فقط</div><header class="navbar app-topbar"><div class="container-xl d-flex justify-content-between gap-3"><div class="d-flex align-items-center gap-2"><span class="text-secondary small">${names[role]}</span>${button('تحديث','refresh','data-refresh','ghost-secondary')}</div><a class="d-flex align-items-center gap-2 text-reset text-decoration-none" href="${link('profile')}"><span class="avatar avatar-sm">${e(user.name.slice(0,1))}</span><div><strong class="d-block small">${e(user.name)}</strong><span class="user-email text-secondary small">${role==='bank'?(user.staffType==='representative'?'الممثل الرسمي':'موظف بنك الدم'):role==='admin'?'مدير النظام':'متبرع'}</span></div></a></div></header><main id="main-content"><div class="page-header"><div class="container-xl"><div class="row g-3 align-items-center"><div class="col"><div class="page-pretitle">حياة / ${names[role]}</div><h1 class="page-title" id="page-title">${title}</h1><p class="text-secondary mb-0 mt-2 small" id="page-description"></p></div><div class="col-12 col-md-auto ms-auto" id="page-actions"></div></div></div></div><div class="page-body"><div class="container-xl" id="view-content"></div></div></main><footer class="footer footer-transparent mt-auto"><div class="container-xl text-secondary small d-flex flex-wrap justify-content-between gap-2"><span>© 2026 حياة · نموذج Frontend</span><span>القبول استجابة؛ التبرع يوثّقه بنك الدم.</span></div></footer></div>`;
 const drawer=$('#sidebar-menu'),drawerToggle=$('[data-bs-target="#sidebar-menu"]');drawer?.addEventListener('shown.bs.offcanvas',()=>drawerToggle?.setAttribute('aria-expanded','true'));drawer?.addEventListener('hidden.bs.offcanvas',()=>drawerToggle?.setAttribute('aria-expanded','false'));
 $$('[data-logout]').forEach(b=>b.onclick=H.logout);$('[data-refresh]')?.addEventListener('click',()=>{showSkeleton();requestAnimationFrame(()=>{D.syncMatches();safeRender()})});$('[data-reset]')?.addEventListener('click',()=>H.confirmDialog({title:'إعادة ضبط التجربة؟',description:'ستُحذف الحسابات والسجلات التجريبية التي أُنشئت في هذا المتصفح وتعود البيانات الابتدائية.',confirm:'إعادة الضبط',danger:true,onConfirm:()=>{D.reset();location.href=url('login.html')}}));
}
function kpis(items){return `<div class="row row-cards mb-4">${items.map(([label,value,ic,note])=>`<div class="col-6 col-xl-3"><div class="card h-100"><div class="card-body"><div class="d-flex align-items-center justify-content-between gap-2"><div class="text-secondary small">${label}</div><span class="kpi-icon ${ic==='droplet'?'red':''}">${i(ic)}</span></div><div class="kpi-number mt-3" ${typeof value==='number'?`data-count="${value}" data-counter-key="${e(label)}"`:''}>${value}</div><div class="text-secondary small mt-2">${note}</div></div></div></div>`).join('')}</div>`}
function requestCards(requests){if(!requests.length)return empty('ما في طلبات موجهة إلك حاليًا','تأكد من فصيلتك ومنطقتك وتوفرك في الملف الشخصي.',`<a class="btn btn-outline-secondary" href="${link('profile')}">تحديث الملف الشخصي</a>`);return requests.map(r=>`<div class="card mb-3"><div class="card-body"><div class="d-flex align-items-start gap-3"><span class="avatar avatar-lg blood-avatar">${blood(r.bloodType)}</span><div class="flex-fill"><div class="d-flex flex-wrap gap-2 align-items-center mb-1"><h3 class="mb-0">${e(bank(r.bankId)?.name)}</h3>${urgency(r.urgency)} ${badge(r.status)}</div><p class="text-secondary small mb-2">${i('map-pin')} ${e(bank(r.bankId)?.city)}، ${e(bank(r.bankId)?.area)} · ${r.units} وحدات · نطاق ${r.radius} كم</p><div class="d-flex flex-wrap gap-2"><a class="btn btn-outline-secondary" href="${link('request-details','?id='+encodeURIComponent(r.id))}">تفاصيل الطلب ${i('arrow-left')}</a>${responseFor(r)?responseBadge(responseFor(r)):''}</div></div></div></div></div>`).join('')}
function dashboard(){const donations=scopedDonations().filter(d=>d.status==='confirmed'),requests=scopedRequests();$('#page-description').textContent=`أهلًا ${user.name}، ${role==='donor'?'كل خطوة منك بتترك أثر.':'هذه نظرة على النشاط التجريبي في حياة.'}`;
 if(role==='donor'){const commitment=D.activeCommitment(user.id,state),active=requests.filter(r=>r.status==='active'&&(commitment?.requestId===r.id||D.matches(user,r,state)));return kpis([['فصيلة الدم',blood(user.bloodType),'droplet','فصيلة معلنة ذاتيًا'],['نقاط العطاء',D.points(user.id),'award','5 نقاط لكل تبرع مؤكّد'],['التبرعات المؤكدة',donations.length,'heart-handshake','من سجل التبرعات فقط'],[commitment?'تنسيق جارٍ':'طلبات موجهة',active.length,'bell',commitment?'استجابتك لطلب واحد':'ترشيح تنسيقي أولي']])+`<div class="row g-4"><section class="col-lg-8"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h3 mb-0">${commitment?'طلبك الحالي':'نداءات قريبة من عطائك'}</h2><a href="${link('notifications')}" class="small text-primary">عرض الكل</a></div>${requestCards(active.slice(0,2))}</section><aside class="col-lg-4"><div class="card mb-3"><div class="card-body"><span class="avatar bg-teal-lt mb-3">${i('heart-check')}</span><h2 class="h3">توفرك يصنع فرقًا</h2><p class="text-secondary small">حالتك الحالية: <strong>${commitment?'مرتبط بطلب حالي':user.available===false?'غير متاح للتنسيق':'متاح للتنسيق الأولي'}</strong>. هذه الحالة ليست شهادة أهلية طبية.</p><a class="btn btn-outline-secondary w-100" href="${link('eligibility')}">إدارة التوفر</a></div></div><div class="card"><div class="card-body"><h2 class="h3">عطاؤك محفوظ</h2><p class="text-secondary small">آخر تبرع مؤكد: ${date(donations.map(d=>d.donatedAt).sort().at(-1))}</p><a class="btn btn-ghost-primary" href="${link('history')}">سجل التبرعات ${i('arrow-left')}</a></div></div></aside></div>`+medical}
 const accepted=state.donor_responses.filter(x=>x.status==='accepted'&&requests.some(r=>r.id===x.requestId)).length;$('#page-actions').innerHTML=`<a class="btn btn-primary" href="${link(role==='bank'?'create-request':'blood-banks')}">${i('plus')} ${role==='bank'?'إنشاء طلب دم':'إدارة المؤسسات'}</a>`;
 const metrics=role==='bank'?[['طلبات نشطة',requests.filter(r=>r.status==='active').length,'clipboard-list','في نطاق مؤسستك'],['استجابات مقبولة',accepted,'users','ليست تبرعات مؤكدة'],['تبرعات مؤكدة',donations.length,'droplet','موثقة بواسطة الموظفين'],['نقاط صافية',state.point_transactions.filter(p=>p.bankId===user.bankId).reduce((a,p)=>a+p.delta,0),'award','تشمل التصحيحات']]:[['المتبرعون',H.allUsers().filter(u=>u.role==='donor').length,'users','حسابات افتراضية'],['بنوك الدم',state.banks.length,'building-hospital','مؤسسات النموذج'],['طلبات نشطة',requests.filter(r=>r.status==='active').length,'clipboard-list','في جميع المؤسسات'],['تبرعات مؤكدة',donations.length,'droplet','بعد استبعاد التصحيحات']];
 return kpis(metrics)+`<div class="row g-4"><section class="col-xl-8"><div class="card"><div class="card-header"><h2 class="card-title">آخر طلبات الدم</h2><a class="ms-auto small text-primary" href="${link('requests')}">كل الطلبات</a></div>${requestTable(requests.slice(0,5),true)}</div></section><aside class="col-xl-4"><div class="card mb-3"><div class="card-header"><h2 class="card-title">النشاط حسب الفصيلة</h2></div><div class="card-body">${chart(donations)}<p class="text-secondary small mt-3 mb-0">عدد التبرعات المؤكدة حسب الفصيلة المعلنة وقت توثيقها.</p></div></div><div class="card"><div class="card-body"><h2 class="h3">${role==='bank'?'توثيق تبرع مباشر':'تقارير الإشراف الصحي'}</h2><p class="text-secondary small">${role==='bank'?'تقدر توثّق تبرعًا مكتملًا، حتى لو ما ارتبط بطلب في حياة.':'تجميع نشاط المؤسسات، دون عرض بيانات المتبرعين الشخصية في التقرير الصحي.'}</p><a class="btn btn-outline-secondary w-100" href="${link(role==='bank'?'record-donation':'health-reports')}">${role==='bank'?'توثيق تبرع':'استعراض التقارير'}</a></div></div></aside></div>`+medical;
}
function chartBlock(title,labels,datasets,type='bar'){
 const spec={type,labels,datasets};
 return `<section class="card h-100"><div class="card-header"><h2 class="card-title">${e(title)}</h2></div><div class="card-body"><div class="hayat-chart"><canvas data-chart="${e(JSON.stringify(spec))}" role="img" aria-label="${e(title)}؛ القيم في الجدول التالي."></canvas></div><details class="mt-3 chart-fallback"><summary class="text-secondary">عرض بيانات الرسم في جدول</summary><div class="table-responsive" tabindex="0" role="region" aria-label="بيانات ${e(title)}"><table class="table table-sm mb-0"><caption class="visually-hidden">${e(title)}</caption><thead><tr><th scope="col">الفئة</th>${datasets.map(set=>`<th scope="col">${e(set.label)}</th>`).join('')}</tr></thead><tbody>${labels.map((label,index)=>`<tr><th scope="row"><bdi>${e(label)}</bdi></th>${datasets.map(set=>`<td>${set.data[index]}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div></section>`;
}
function chart(donations){return chartBlock('التبرعات حسب الفصيلة',D.groups,[{label:'تبرعات مؤكدة',data:D.groups.map(g=>donations.filter(d=>(d.bloodType||person(d.donorId)?.bloodType)===g).length)}])}
function reportCharts(donations,ledger){
 const requests=filterData(scopedRequests(),r=>`${r.id} ${r.bloodType} ${bank(r.bankId)?.name}`);
 const days=[...new Set(requests.map(r=>r.createdAt.slice(0,10)))].sort();
 const institutions=state.banks.filter(b=>(role==='admin'||b.id===user.bankId)&&(!bankFilter||b.id===bankFilter));
 return `<div class="row g-4 mb-4"><div class="col-lg-4">${chart(donations.filter(d=>d.status==='confirmed'))}</div><div class="col-lg-4">${chartBlock('الطلبات حسب تاريخ النشر',days.length?days:['لا توجد طلبات'],[{label:'طلبات منشورة',data:days.length?days.map(day=>requests.filter(r=>r.createdAt.slice(0,10)===day).length):[0]}],'line')}</div><div class="col-lg-4">${chartBlock('النقاط الصافية حسب المؤسسة',institutions.map(b=>b.name),[{label:'نقاط صافية',data:institutions.map(b=>ledger.filter(p=>p.bankId===b.id).reduce((sum,p)=>sum+p.delta,0))}])}</div></div>`;
}
function requestTable(rows,compact=false){return table(['الفصيلة / الطلب','المؤسسة','الوحدات','الردود المقبولة','الحالة',''],rows,r=>{const fulfilled=state.donations.filter(d=>d.requestId===r.id&&d.status==='confirmed').length,accepted=state.donor_responses.filter(x=>x.requestId===r.id&&x.status==='accepted').length;return `<tr><td><strong>${blood(r.bloodType)}</strong><div class="small text-secondary">${urgency(r.urgency)}</div></td><td>${e(bank(r.bankId)?.name)}</td><td><span class="text-nowrap" aria-label="${fulfilled} مؤكدة من ${r.units} مطلوبة">${fulfilled} / ${r.units}</span></td><td>${accepted}</td><td>${badge(r.status)}</td><td><a class="btn btn-outline-secondary" href="${link('request-details','?id='+encodeURIComponent(r.id))}">تفاصيل</a></td></tr>`})}
function requestsPage(){const rows=filterData(scopedRequests(),r=>`${r.id} ${r.bloodType} ${bank(r.bankId)?.name}`);return `<div class="card"><div class="card-header"><h2 class="card-title">طلبات الدم</h2>${role==='bank'?`<a class="btn btn-primary ms-auto" href="${link('create-request')}">${i('plus')} طلب جديد</a>`:''}</div>${toolbar({statuses:['active','fulfilled','cancelled'],banks:role==='admin'})}${requestTable(rows)}</div>`}
function detail(){const requestedId=new URLSearchParams(location.search).get('id'),commitment=role==='donor'?D.activeCommitment(user.id,state):null;if(commitment&&requestedId!==commitment.requestId)return empty('لديك استجابة جارية','النداءات الأخرى مخفية مؤقتًا. تابع طلبك الحالي أو تراجع عن الاستجابة قبل اختيار طلب آخر.',`<a class="btn btn-primary" href="${link('request-details','?id='+encodeURIComponent(commitment.requestId))}">متابعة طلبي الحالي</a>`);const r=scopedRequests().find(r=>r.id===new URLSearchParams(location.search).get('id'));if(!r)return empty('الطلب غير متاح','هذا الطلب غير موجود ضمن نطاق حسابك.',`<a class="btn btn-outline-secondary" href="${link(role==='donor'?'notifications':'requests')}">العودة للطلبات</a>`);$('#page-actions').innerHTML=`<a class="btn btn-outline-secondary" href="${link(role==='donor'?'notifications':'requests')}">${i('arrow-right')} العودة للطلبات</a>`;const b=bank(r.bankId),responses=state.donor_responses.filter(x=>x.requestId===r.id),confirmed=state.donations.filter(d=>d.requestId===r.id&&d.status==='confirmed');return `<div class="row g-4"><div class="col-lg-8"><div class="card mb-4"><div class="card-header"><h2 class="card-title">طلب تبرع ${blood(r.bloodType)}</h2><div class="ms-auto d-flex gap-2">${urgency(r.urgency)} ${badge(r.status)}</div></div><div class="card-body"><div class="row g-4"><div class="col-sm-6"><div class="text-secondary small">المؤسسة</div><strong>${e(b?.name)}</strong><div class="text-secondary small mt-2">${i('map-pin')} ${e(b?.city)}، ${e(b?.area)}</div><div class="ltr small mt-2">${e(b?.contact)}</div></div><div class="col-sm-6"><div class="text-secondary small">الاحتياج / النطاق</div><strong>${r.units} وحدات · ${r.radius} كم</strong><div class="text-secondary small mt-2">تاريخ النشر ${date(r.createdAt)}</div></div></div><p class="mt-4 mb-0 text-secondary">${e(r.notes||'لا توجد ملاحظات إضافية.')}</p>${r.closeReason?`<div class="alert alert-info mt-3">سبب الإغلاق: ${e(r.closeReason)}</div>`:''}</div><div class="card-footer d-flex flex-wrap gap-2">${role==='donor'?donorRequestActions(r):(r.status==='active'?`${role==='bank'?button('تعديل الطلب','edit',`data-edit-request="${r.id}"`,'outline-secondary'):''}${role==='bank'?button('إغلاق كمستوفى','check',`data-close="fulfilled" data-id="${r.id}" ${role==='bank'&&confirmed.length<r.units?'disabled aria-describedby="fulfillment-note"':''}`,'outline-success'):''}${button(role==='admin'?'إيقاف الطلب':'إلغاء الطلب','x',`data-close="cancelled" data-id="${r.id}"`,'outline-danger')}`:'')} ${role==='bank'&&r.status==='active'?`<a class="btn btn-outline-secondary" href="${link('donors','?request='+encodeURIComponent(r.id))}">${i('user-search')} المتبرعون المرشحون</a><a class="btn btn-primary" href="${link('record-donation','?request='+encodeURIComponent(r.id))}">توثيق تبرع فعلي</a>`:''}</div></div>${role!=='donor'?`<p class="body-note mb-4" id="fulfillment-note">الإغلاق كمستوفى يتطلب توثيق ${r.units} وحدات؛ تم توثيق ${confirmed.length}. يمكن إلغاء الطلب مع تسجيل السبب.</p><div class="card"><div class="card-header"><h2 class="card-title">استجابات المتبرعين</h2></div>${table(['المتبرع','الاستجابة','التاريخ'],responses,x=>`<tr><td>${e(person(x.donorId)?.name||'حساب غير متاح')}</td><td>${responseBadge(x)}</td><td>${date(x.at)}</td></tr>`)}</div>`:''}</div><aside class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h3">استجابة اليوم، وأثر لاحقًا</h2><div class="d-flex justify-content-between border-bottom py-3"><span>الاستجابات المقبولة</span><strong>${responses.filter(x=>x.status==='accepted').length}</strong></div><div class="d-flex justify-content-between py-3"><span>التبرعات المؤكدة</span><strong>${confirmed.length}</strong></div><p class="text-secondary small mb-0">قبول الطلب لا يضيف نقاطًا ولا يسجّل تبرعًا. تُضاف 5 نقاط بعد توثيق التبرع الفعلي فقط.</p>${role!=='donor'?`<div class="mt-3"><a class="btn btn-outline-secondary w-100" href="${link(role==='bank'?'reports':'donations','?request='+encodeURIComponent(r.id))}">سجل تبرعات هذا الطلب</a></div>`:''}${role==='donor'&&responseFor(r)?`<div class="mt-3">استجابتك: ${responseBadge(responseFor(r))}</div>`:''}</div></div></aside></div>`+medical}
function notifications(){const commitment=D.activeCommitment(user.id,state),notifications=state.notifications.filter(n=>n.donorId===user.id&&(!commitment||n.requestId===commitment.requestId||n.donationId)&&(!query||`${n.title} ${n.body}`.toLowerCase().includes(query.toLowerCase()))&&(!filter||filter===(n.read?'read':'unread'))).sort((a,b)=>sort==='name'?a.title.localeCompare(b.title,'ar'):a.at.localeCompare(b.at)*(sort==='oldest'?1:-1));return `<div class="row g-4"><div class="col-lg-8"><div class="card"><div class="card-header"><h2 class="card-title">صندوق النداءات</h2>${button('تحديد الكل كمقروء','checks','data-read-all','ghost-primary ms-auto')}</div>${toolbar({statuses:['unread','read']})}<div class="list-group list-group-flush">${notifications.length?notifications.map(n=>`<div class="list-group-item ${n.read?'':'notification-unread'}"><div class="d-flex gap-3"><span class="avatar bg-${n.read?'secondary':'red'}-lt">${i('bell')}</span><div class="flex-fill"><div class="d-flex flex-wrap gap-2"><h3 class="h4 mb-1">${e(n.title)}</h3>${n.read?'':'<span class="badge bg-red-lt">جديد</span>'}</div><p class="text-secondary small mb-2">${e(n.body)}</p><div class="d-flex flex-wrap gap-2 align-items-center"><span class="text-secondary small">${date(n.at)}</span><a class="btn btn-outline-secondary" data-read="${n.id}" href="${n.donationId?link('history'):link('request-details','?id='+encodeURIComponent(n.requestId))}">${n.donationId?'سجل التبرعات':'عرض الطلب'}</a></div></div></div></div>`).join(''):empty('لا توجد إشعارات بعد','عند نشر طلب مطابق يظهر هنا.')}</div></div></div><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h3">طلبات تناسب منطقتك</h2><p class="text-secondary small">المطابقة التجريبية حسب الفصيلة المعلنة والتوفر ومسافة افتراضية. لا تصل رسائل SMS أو بريد حقيقي.</p><a href="${link('profile')}" class="btn btn-outline-secondary w-100">تحديث تفضيلاتي</a></div></div></div></div>`+medical}
function profile(){const donor=role==='donor';return formWrap('profile-form','بيانات حسابك',field('name','الاسم','text',user.name,'required minlength="2" maxlength="100"')+`<div class="row"><div class="col-md-6">${field('email','البريد الإلكتروني','email',user.email,'required dir="ltr"')}</div><div class="col-md-6">${field('phone','رقم الهاتف','tel',user.phone,'required dir="ltr" minlength="8" maxlength="15"')}</div></div><div class="alert alert-info small">تغيير البريد يستلزم إعادة تأكيده في صندوق البريد التجريبي.</div>`+(donor?`<div class="row"><div class="col-md-4">${select('bloodType','الفصيلة المعلنة',[['unknown','لا أعرف'],...groupOptions],user.bloodType,'required')}</div><div class="col-md-4">${field('city','المدينة','text',user.city,'required list="cities"')}</div><div class="col-md-4">${field('area','المنطقة','text',user.area,'required list="areas"')}</div></div>${locationLists()}<p class="text-secondary small">للمطابقة التجريبية، اختر منطقة من القائمة. العناوين الأخرى تُحفظ دون تقدير مسافة.</p>${field('lastDonation','آخر تبرع معلن (اختياري، لا يمنح نقاطًا)','date',user.lastDonation||'',`max="${D.today()}"`)}<label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="available" ${user.available!==false?'checked':''}><span class="form-check-label">متاح للتنسيق الأولي</span></label><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="notifyEnabled" ${user.notifyEnabled!==false?'checked':''}><span class="form-check-label">تمييز الإشعارات الجديدة داخل التطبيق (محاكاة)</span></label>`:''))+medical}
function locationLists(){return `<datalist id="cities">${Object.keys(D.locations).map(c=>`<option value="${c}">`).join('')}</datalist><datalist id="areas">${Object.values(D.locations).flatMap(a=>Object.keys(a)).map(a=>`<option value="${a}">`).join('')}</datalist>`}
function eligibility(){const last=[...scopedDonations().filter(d=>d.status==='confirmed').map(d=>d.donatedAt),user.lastDonation].filter(Boolean).sort().at(-1);const days=last?Math.max(0,Math.floor((Date.now()-Date.parse(last))/86400000)):null;return `<div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body p-4"><span class="avatar bg-teal-lt mb-3">${i('heart-check')}</span><h2 class="h2">توفرك للتنسيق</h2><p class="text-secondary">حالتك في حياة تساعد المؤسسة على التواصل معك، ولا تحدد أهليتك للتبرع طبيًا.</p><div class="border-top py-3 d-flex justify-content-between"><span>آخر تبرع مسجل أو معلن</span><strong>${date(last)}</strong></div><div class="border-top py-3 d-flex justify-content-between"><span>الوقت منذ آخر تبرع</span><strong>${days===null?'غير معروف':`${days} يوم`}</strong></div><div class="border-top py-3 d-flex justify-content-between"><span>توفر التنسيق الحالي</span>${badge(user.available===false?'suspended':'active')}</div><a class="btn btn-primary mt-2" href="${link('profile')}">تحديث توفري ${i('arrow-left')}</a></div></div></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h3">متى أقدر أتبرع مرة ثانية؟</h2><p class="text-secondary">لا تعرض هذه النسخة موعد أهلية أو موافقة طبية، لأن الفترة والمعايير تحتاج اعتماد الجهة الطبية. تواصل مع بنك الدم واتبع الفحوصات والتعليمات المختصة.</p><p class="small text-secondary mb-0">تاريخ معلن في الملف لا يدخل في عدد التبرعات أو نقاطك.</p></div></div></div></div>`+medical}
function donationTable(rows,corrections=false){return table(['مرجع التبرع','المتبرع','المؤسسة','التاريخ','نوع التبرع','التأكيد','الحالة',...(corrections?['الإجراء']:[])],rows,d=>`<tr><td><strong class="ltr">${e(d.reference)}</strong><div class="text-secondary small ltr record-id">${e(d.id)}</div></td><td>${e(person(d.donorId)?.name||'—')}</td><td>${e(bank(d.bankId)?.name)}</td><td>${date(d.donatedAt)}</td><td>${d.requestId?'مرتبط بطلب':'مباشر'}</td><td>${e(person(d.confirmedBy)?.name||'موظف تجريبي')}<div class="text-secondary small">${date(d.confirmedAt)}</div></td><td>${badge(d.status)}</td>${corrections?`<td>${d.status==='confirmed'?button('تصحيح','edit',`data-correct="${d.id}"`,'outline-danger'):`<span class="small">${e(d.correctionReason)}</span>`}</td>`:''}</tr>`)}
function history(){const rows=filterData(scopedDonations().filter(d=>d.status==='confirmed'),d=>`${d.reference} ${bank(d.bankId)?.name}`);return `<div class="card"><div class="card-header"><h2 class="card-title">سجل عطائك المؤكّد</h2></div>${toolbar({dates:true,exportable:true})}${donationTable(rows)}</div><p class="body-note mt-3">يظهر التبرع هنا بعد تأكيد المؤسسة. التصحيحات محفوظة في حركات النقاط والتدقيق.</p>`}
function pointsPage(){const rows=state.point_transactions.filter(p=>role==='admin'||p.donorId===user.id);const filtered=filterData(rows,p=>`${person(p.donorId)?.name} ${p.donationId} ${p.reason}`);return (role==='donor'?kpis([['رصيدك المعنوي',D.points(user.id),'award','مجموع حركات النقاط'],['تبرعات مؤكدة',scopedDonations().filter(d=>d.status==='confirmed').length,'droplet','لكل تبرع +5'],['حركات التصحيح',rows.filter(p=>p.type==='correction').length,'receipt','تظهر بشفافية في السجل'],['نقاط القبول',0,'check','الاستجابة لا تمنح نقاطًا']]):'')+`<div class="card mb-4"><div class="card-header"><h2 class="card-title">حركات النقاط</h2></div>${toolbar({banks:role==='admin',dates:true,exportable:true})}${table(['المتبرع','التبرع','الحركة','السبب','المؤسسة','بواسطة','التاريخ'],filtered,p=>`<tr><td>${e(person(p.donorId)?.name)}</td><td class="ltr record-id">${e(p.donationId)}</td><td><span class="badge bg-${p.delta>0?'teal':'red'}-lt blood-type">${p.delta>0?'+':''}${p.delta}</span></td><td>${e(p.reason)}</td><td>${e(bank(p.bankId)?.name)}</td><td>${e(person(p.actorId)?.name)}</td><td>${date(p.at)}</td></tr>`)}</div>`+(role==='admin'?auditPanel():'')}
function auditPanel(){
 const rows=filterData(state.audit_logs,a=>`${a.action} ${a.subjectId} ${a.details} ${person(a.actorId)?.name} ${bank(a.bankId)?.name}`);
 return `<section class="card" aria-labelledby="audit-title"><div class="card-header"><h2 class="card-title" id="audit-title">سجل التدقيق</h2><div class="ms-auto btn-list">${button('تصدير التدقيق','download','data-export data-table="table-audit"','outline-secondary')}<a class="btn btn-outline-secondary" href="${link('donations')}">مراجعة وتصحيح تبرع</a></div></div><div class="card-body py-3 text-secondary small">البحث والمؤسسة والتاريخ أعلاه يصفّون حركات النقاط والتدقيق معًا. كل عملية تحفظ الفاعل والوقت والسجل والسبب.</div>${table(['العملية','بواسطة','المؤسسة','السجل المرتبط','السبب / التفاصيل','الوقت'],rows,a=>`<tr><td>${e(a.action)}</td><td>${e(person(a.actorId)?.name||a.actorId)}</td><td>${e(bank(a.bankId)?.name||'إدارة النظام')}</td><td class="ltr record-id">${e(a.subjectId)}</td><td>${e(a.details||'—')}</td><td>${date(a.at)}<div class="small text-secondary">${new Date(a.at).toLocaleTimeString('ar-PS',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</div></td></tr>`,{key:'audit',caption:'سجل التدقيق'})}</section>`;
}
function createRequestForm(){return formWrap('request-form','نداء جديد من مؤسستك',`<p class="text-secondary small">المؤسسة: <strong>${e(bank(user.bankId)?.name)}</strong> · ${e(bank(user.bankId)?.city)}، ${e(bank(user.bankId)?.area)}</p><div class="row"><div class="col-md-6">${select('bloodType','فصيلة الدم',groupOptions,'O+','required')}</div><div class="col-md-6">${field('units','الوحدات المطلوبة','number',1,'required min="1" max="100" step="1"')}</div><div class="col-md-6">${select('urgency','الأولوية',[['normal','اعتيادي'],['high','عاجل'],['critical','حرج']],'high','required')}</div><div class="col-md-6">${field('radius','نطاق البحث الافتراضي (كم)','number',15,'required min="1" max="100"')}</div></div><div class="mb-3"><label class="form-label" for="notes">ملاحظات تنسيق (دون بيانات مرضى)</label><textarea class="form-control" id="notes" name="notes" rows="3" maxlength="400"></textarea></div><div class="alert alert-info">سيظهر تنبيه داخل التطبيق للحسابات التجريبية المطابقة. تُستخدم إحداثيات اصطناعية، ومطابقة فصيلة متطابقة فقط.</div>`,'نشر الطلب التجريبي')+medical}
function donorsPage(){const requestId=new URLSearchParams(location.search).get('request');const request=state.requests.find(r=>r.id===requestId&&r.bankId===user.bankId);let donors=H.allUsers().filter(u=>u.role==='donor'&&u.status==='active'&&u.verified);if(requestId&&!request)return empty('الطلب غير متاح','اختر طلبًا من مؤسستك.',`<a class="btn btn-outline-secondary" href="${link('requests')}">إدارة الطلبات</a>`);if(request)donors=donors.filter(d=>D.matches(d,request,state));if(query)donors=donors.filter(d=>`${d.name} ${d.phone} ${d.email} ${d.bloodType} ${d.city}`.toLowerCase().includes(query.toLowerCase()));if(filter)donors=donors.filter(d=>d.bloodType===filter);return `<div class="alert alert-info">لمتبرع غير مسجّل: ساعده بفتح <a href="${url('register.html')}" target="_blank" rel="noopener">صفحة التسجيل العامة</a> على جواله. يكتب المتبرع كلمة مروره ورمز بريده بنفسه، ثم ابحث عن حسابه هنا.</div><div class="card"><div class="card-header"><h2 class="card-title">${request?'مرشحون للطلب':'البحث عن حساب متبرع'}</h2>${request?`<a class="btn btn-outline-secondary ms-auto" href="${link('request-details','?id='+encodeURIComponent(request.id))}">العودة للطلب</a>`:''}</div><div class="data-toolbar"><input class="form-control" id="table-search" type="search" placeholder="الاسم أو الهاتف أو البريد" aria-label="البحث عن متبرع" value="${e(query)}"><select class="form-select" id="status-filter" aria-label="تصفية الفصيلة"><option value="">كل الفصائل</option>${D.groups.map(g=>`<option ${filter===g?'selected':''}>${g}</option>`).join('')}</select></div>${table(['الاسم','الفصيلة المعلنة','المنطقة','التوفر','الإجراء'],donors,d=>`<tr><td><strong>${e(d.name)}</strong><div class="text-secondary small ltr">${e(d.phone)}</div></td><td>${blood(d.bloodType)}</td><td>${e(d.city)}، ${e(d.area)}</td><td>${d.available===false?'غير متاح':'متاح للتنسيق'}</td><td><a class="btn btn-outline-secondary" href="${link('record-donation','?donor='+encodeURIComponent(d.id)+(request?'&request='+encodeURIComponent(request.id):''))}">توثيق تبرع مكتمل</a></td></tr>`)}</div>`+medical}
function recordForm(){
 const p=new URLSearchParams(location.search),donors=H.allUsers().filter(d=>d.role==='donor'&&d.verified&&d.status==='active');
 const requests=state.requests.filter(r=>r.bankId===user.bankId&&r.status==='active');
 if(p.get('request')&&!requests.some(r=>r.id===p.get('request')))return empty('الطلب غير متاح للتوثيق','الطلب مغلق أو لا يتبع مؤسستك. اختر طلبًا نشطًا، أو افتح نموذج التبرع المباشر صراحة.',`<a class="btn btn-outline-secondary" href="${link('requests')}">إدارة الطلبات</a><a class="btn btn-primary" href="${link('record-donation')}">توثيق تبرع مباشر</a>`);
 return `<div class="alert alert-info">للمتبرع غير المسجّل: افتح <a href="${url('register.html')}" target="_blank" rel="noopener">التسجيل العام</a> على جواله؛ يكتب كلمة المرور ورمز التفعيل بنفسه، ثم ابحث عن حسابه هنا.</div>`+formWrap('donation-form','توثيق تبرع فعلي مكتمل',`<div class="alert alert-warning">استخدم هذا الإجراء بعد إتمام التبرع الفعلي فقط؛ قبول الطلب أو حضور المتبرع لا يكفي.</div>${field('donor-search','تصفية حسابات المتبرعين بالاسم أو الهاتف','search','','autocomplete="off"')}<div id="donor-select-wrap">${select('donorId','حساب المتبرع',[['','اختر متبرعًا مفعّلًا'],...donors.map(d=>[d.id,`${d.name} · ${d.phone} · ${d.bloodType==='unknown'?'غير معروفة':d.bloodType}`])],p.get('donor')||'','required')}</div>${select('requestId','الطلب المرتبط (اختياري)',[['','تبرع مباشر — دون طلب'],...requests.map(r=>[r.id,`${r.bloodType} · ${r.units} وحدات · ${r.id}`])],p.get('request')||'')}<div class="row"><div class="col-md-6">${field('donatedAt','تاريخ التبرع','date',D.today(),`required max="${D.today()}"`)}</div><div class="col-md-6">${field('reference','مرجع تبرع تجريبي فريد','text','','required minlength="3" maxlength="80" placeholder="DEMO-2026-001"')}</div></div><label class="form-check"><input class="form-check-input" type="checkbox" name="completed" required><span class="form-check-label">أؤكّد أن هذا توثيق محاكى لتبرع مكتمل وليس مجرد قبول أو حضور.</span></label>`,'تأكيد التبرع وإضافة 5 نقاط')+medical;
}
function staffPage(){if(user.staffType!=='representative')return empty('الوصول غير مسموح','إدارة موظفي المؤسسة متاحة للممثل الرسمي فقط.');const users=H.allUsers().filter(u=>u.bankId===user.bankId);return `<div class="row g-4"><div class="col-xl-7"><div class="card"><div class="card-header"><h2 class="card-title">فريق المؤسسة</h2></div>${table(['الاسم','البريد','الصلاحية','الحالة',''],users,u=>`<tr><td>${e(u.name)}</td><td class="ltr">${e(u.email)}</td><td>${u.staffType==='representative'?'ممثل رسمي':'موظف'}</td><td>${badge(u.status)}</td><td>${u.staffType==='employee'?button(u.status==='suspended'?'تفعيل':'إيقاف','user-edit',`data-toggle-user="${u.id}"`,'outline-secondary'):''}</td></tr>`)}</div></div><div class="col-xl-5">${formWrap('staff-form','إضافة موظف للمؤسسة',accountFields(),'إضافة الموظف')}<p class="body-note mt-3">الموظف يملك صلاحيات التشغيل نفسها؛ إدارة الفريق للممثل الرسمي فقط. الحساب الجديد ينتظر تفعيل الموظف عبر رمز في صندوق البريد التجريبي عند تسجيل دخوله.</p></div></div>`}
function accountFields(){return field('name','الاسم','text','','required minlength="2" maxlength="100"')+field('email','البريد التجريبي','email','','required placeholder="name@hayat.demo" dir="ltr"')+field('phone','الهاتف التجريبي','tel','','required minlength="8" maxlength="15" dir="ltr"')+field('password','كلمة مرور تجريبية أولية','password','','required minlength="8" autocomplete="new-password"')}
function banksPage(){
 const rows=state.banks.filter(b=>!query||`${b.name} ${b.city} ${b.area} ${b.contact}`.toLowerCase().includes(query.toLowerCase()));
 return `<div class="row g-4"><div class="col-xl-7"><div class="card"><div class="card-header"><h2 class="card-title">المؤسسات المسجّلة</h2></div>${toolbar()}${table(['المؤسسة','الموقع','الممثل الرسمي','الحالة','الإجراء'],rows,b=>`<tr><td><strong>${e(b.name)}</strong><div class="ltr text-secondary small">${e(b.contact)}</div></td><td>${e(b.city)}، ${e(b.area)}</td><td>${e(H.allUsers().find(u=>u.bankId===b.id&&u.staffType==='representative')?.name||'غير متاح')}</td><td>${badge(b.status)}</td><td><div class="btn-list flex-nowrap">${button('تعديل','edit',`data-edit-bank="${b.id}"`,'outline-secondary')}${button(b.status==='active'?'إيقاف':'تفعيل','building-hospital',`data-toggle-bank="${b.id}"`,'outline-secondary')}</div></td></tr>`)}</div></div><div class="col-xl-5">${formWrap('bank-form','إنشاء مؤسسة وممثلها الأول',field('bankName','اسم بنك الدم','text','','required minlength="3" maxlength="100"')+select('city','مدينة المؤسسة',Object.keys(D.locations).map(c=>[c,c]),'غزة','required')+select('area','منطقة المؤسسة',Object.keys(D.locations['غزة']).map(a=>[a,a]),'الرمال','required')+'<h3 class="section-divider mt-4">الممثل الرسمي الأول</h3>'+accountFields(),'إنشاء المؤسسة والممثل')}</div></div>`;
}
function requestEditor(requestId){
 const request=state.requests.find(r=>r.id===requestId&&r.bankId===user.bankId&&r.status==='active');if(role!=='bank'||!request)return;
 const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','request-editor-title');
 el.innerHTML=`<div class="modal-dialog modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><form id="request-edit-form"><div class="modal-header"><h2 class="modal-title" id="request-editor-title">تعديل طلب الدم</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body">${select('edit-bloodType','الفصيلة المعلنة',groupOptions,request.bloodType,'required')}${field('edit-units','الوحدات المطلوبة','number',request.units,'required min="1" max="100" step="1"')}${select('edit-urgency','الأولوية',[['normal','اعتيادي'],['high','عاجل'],['critical','حرج']],request.urgency,'required')}${field('edit-radius','نطاق التنسيق الافتراضي (كم)','number',request.radius,'required min="1" max="100"')}${field('edit-notes','ملاحظات تنسيق','text',request.notes,'maxlength="400"')}${field('edit-request-reason','سبب التعديل','text','','required minlength="5" maxlength="400"')}<p class="text-secondary small">الفصيلة لا تتغير بعد استجابة جارية أو تبرع مؤكد. تُحفظ القيم السابقة والجديدة مع السبب في التدقيق.</p><div id="request-edit-error" class="text-danger small" role="alert"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">تراجع</button><button type="submit" class="btn btn-primary">حفظ تعديلات الطلب</button></div></form></div></div>`;
 document.body.append(el);const modal=new tabler.Modal(el),previous=document.activeElement;el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove();previous?.focus()},{once:true});
 $('#request-edit-form',el).onsubmit=event=>{event.preventDefault();try{D.editRequest(requestId,{bloodType:$('#edit-bloodType',el).value,units:$('#edit-units',el).value,urgency:$('#edit-urgency',el).value,radius:$('#edit-radius',el).value,notes:$('#edit-notes',el).value,reason:$('#edit-request-reason',el).value});modal.hide();render();H.toast('تم تعديل الطلب وحفظ السبب.')}catch(error){$('#request-edit-error',el).textContent=error.message}};modal.show();
}
function bankEditor(bankId){
 const institution=bank(bankId);if(role!=='admin'||!institution)return;
 const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','bank-editor-title');
 el.innerHTML=`<div class="modal-dialog modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><form id="bank-edit-form"><div class="modal-header"><h2 class="modal-title" id="bank-editor-title">إعدادات المؤسسة</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body">${field('edit-bankName','اسم المؤسسة','text',institution.name,'required minlength="3" maxlength="100"')}${field('edit-contact','بريد تواصل المؤسسة','email',institution.contact,'required dir="ltr"')}${select('edit-city','المدينة',Object.keys(D.locations).map(c=>[c,c]),institution.city,'required')}${select('edit-area','المنطقة',Object.keys(D.locations[institution.city]||{}).map(a=>[a,a]),institution.area,'required')}${field('edit-reason','سبب التعديل (يُحفظ في التدقيق)','text','','required minlength="5" maxlength="400"')}<p class="text-secondary small">تعديل الموقع يحدّث الترشيح الأولي للطلبات النشطة. بيانات الدخول للممثل والموظفين تُدار من حساباتهم.</p><div class="text-danger small" role="alert" id="bank-edit-error"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">تراجع</button><button type="submit" class="btn btn-primary">حفظ الإعدادات</button></div></form></div></div>`;
 const previous=document.activeElement;document.body.append(el);const modal=new tabler.Modal(el);
 el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove();previous?.focus()},{once:true});
 $('#edit-city',el).onchange=()=>{$('#edit-area',el).innerHTML=Object.keys(D.locations[$('#edit-city',el).value]||{}).map(a=>`<option value="${e(a)}">${e(a)}</option>`).join('')};
 $('#bank-edit-form',el).onsubmit=event=>{event.preventDefault();try{D.updateBank(bankId,{bankName:$('#edit-bankName',el).value,contact:$('#edit-contact',el).value,city:$('#edit-city',el).value,area:$('#edit-area',el).value,reason:$('#edit-reason',el).value});modal.hide();render();H.toast('تم تحديث المؤسسة وحفظ سبب التعديل.')}catch(error){$('#bank-edit-error',el).textContent=error.message}};
 modal.show();
}
function usersPage(){const rows=filterData(H.allUsers(),u=>`${u.name} ${u.email} ${u.role}`);return `<div class="card"><div class="card-header"><h2 class="card-title">حسابات المنصة</h2></div>${toolbar({statuses:['active','pending_activation','pending_verification','suspended']})}${table(['المستخدم','نوع الحساب','المؤسسة','الحالة','الإجراء'],rows,u=>`<tr><td><strong>${e(u.name)}</strong><div class="ltr text-secondary small">${e(u.email)}</div></td><td>${u.role==='donor'?'متبرع':u.role==='bank'?(u.staffType==='representative'?'ممثل مؤسسة':'موظف بنك دم'):'مدير نظام'}</td><td>${e(bank(u.bankId)?.name||'—')}</td><td>${badge(u.status)}</td><td>${u.role!=='admin'?button(u.status==='suspended'?'تفعيل':'إيقاف','user-edit',`data-toggle-user="${u.id}"`,'outline-secondary'):'<span class="text-secondary">حساب الإدارة</span>'}</td></tr>`)}</div>`}
function reports(){
 const requestId=new URLSearchParams(location.search).get('request');
 const donations=scopedDonations().filter(d=>!requestId||d.requestId===requestId);
 const rows=filterData(donations,d=>`${d.reference} ${d.id} ${person(d.donorId)?.name} ${bank(d.bankId)?.name}`);
 const ledger=state.point_transactions.filter(p=>(role==='admin'||p.bankId===user.bankId)&&(!requestId||donations.some(d=>d.id===p.donationId)));
 const visibleLedger=filterData(ledger,p=>`${p.donationId} ${state.donations.find(d=>d.id===p.donationId)?.reference} ${person(p.donorId)?.name} ${p.reason} ${bank(p.bankId)?.name}`,{ignoreStatus:true});
 const summary=role==='bank'?kpis([['تبرعات مؤكدة',rows.filter(d=>d.status==='confirmed').length,'droplet','ضمن تصفية التبرعات'],['توثيقات مصححة',rows.filter(d=>d.status==='corrected').length,'receipt','أصل السجل محفوظ'],['النقاط الصافية',visibleLedger.reduce((sum,p)=>sum+p.delta,0),'award','ضمن فترة حركات النقاط'],['حركات النقاط',visibleLedger.length,'list-check','منح وتصحيحات المؤسسة']]):'';
 return summary+reportCharts(rows,visibleLedger)+(requestId?`<div class="alert alert-info d-flex flex-wrap gap-2 align-items-center">يعرض سجلات الطلب المحدد فقط. <a class="ms-auto" href="${link(role==='bank'?'reports':'donations')}">عرض جميع السجلات</a></div>`:'')+`<div class="card mb-4"><div class="card-header"><h2 class="card-title">${role==='bank'?'كشف تبرعات المؤسسة':'سجلات التبرعات والتصحيح'}</h2>${button('طباعة','printer','data-print','outline-secondary ms-auto')}</div>${toolbar({statuses:['confirmed','corrected'],banks:role==='admin',dates:true,exportable:true})}${donationTable(rows,role==='admin')}</div><p class="body-note mb-4">كل تبرع مؤكد يمنح +5. التصحيح يسجل حركة -5 مع السبب والفاعل، دون حذف السجل. تاريخ كشف التبرعات هو يوم التبرع؛ تاريخ حركات النقاط هو وقت تسجيل الحركة.</p>`+(role==='bank'?`<section class="card" aria-labelledby="bank-points-title"><div class="card-header"><h2 class="card-title" id="bank-points-title">حركات نقاط المؤسسة</h2>${button('تصدير حركات النقاط','download','data-export data-table="table-bank-points"','outline-secondary ms-auto')}</div><div class="card-body py-3 text-secondary small">البحث وفترة التاريخ أعلاه ينطبقان على هذا السجل أيضًا. فلتر حالة التبرع يخص كشف التبرعات فقط.</div>${table(['المتبرع','مرجع التبرع','الحركة','السبب','بواسطة','التاريخ'],visibleLedger,p=>`<tr><td>${e(person(p.donorId)?.name)}</td><td><span class="ltr d-block">${e(state.donations.find(d=>d.id===p.donationId)?.reference)}</span><small class="ltr record-id d-block">${e(p.donationId)}</small></td><td><span class="badge bg-${p.delta>0?'teal':'red'}-lt blood-type">${p.delta>0?'+':''}${p.delta}</span></td><td>${e(p.reason)}</td><td>${e(person(p.actorId)?.name)}</td><td>${date(p.at)}</td></tr>`,{key:'bank-points',caption:'حركات نقاط المؤسسة'})}</section>`:'');
}
function healthReports(){let donations=state.donations.filter(d=>d.status==='confirmed');donations=filterData(donations,()=> '');const rows=state.banks.filter(b=>!bankFilter||b.id===bankFilter);return `<div class="alert alert-info">تقرير تجميعي للإشراف الصحي ضمن إدارة النظام. لا يتضمن هوية المتبرعين أو معلومات طبية شخصية.</div><div class="card mb-4"><div class="card-header"><h2 class="card-title">نشاط المؤسسات</h2>${button('طباعة','printer','data-print','outline-secondary ms-auto')}</div>${toolbar({banks:true,dates:true,exportable:true})}${table(['المؤسسة','المدينة','طلبات نشطة','تبرعات مؤكدة','نقاط صافية'],rows,b=>`<tr><td>${e(b.name)}</td><td>${e(b.city)}</td><td>${state.requests.filter(r=>r.bankId===b.id&&r.status==='active'&&(!dateFrom||r.createdAt.slice(0,10)>=dateFrom)&&(!dateTo||r.createdAt.slice(0,10)<=dateTo)).length}</td><td>${donations.filter(d=>d.bankId===b.id).length}</td><td>${state.point_transactions.filter(p=>p.bankId===b.id&&(!dateFrom||p.at.slice(0,10)>=dateFrom)&&(!dateTo||p.at.slice(0,10)<=dateTo)).reduce((a,p)=>a+p.delta,0)}</td></tr>`)}</div>${reportCharts(donations,state.point_transactions.filter(p=>(!bankFilter||p.bankId===bankFilter)&&(!dateFrom||p.at.slice(0,10)>=dateFrom)&&(!dateTo||p.at.slice(0,10)<=dateTo)))}`+medical}
const views={dashboard,notifications,'request-details':detail,eligibility,profile,history,points:pointsPage,requests:requestsPage,'create-request':createRequestForm,donors:donorsPage,'record-donation':recordForm,staff:staffPage,'blood-banks':banksPage,users:usersPage,reports,donations:reports,'health-reports':healthReports};
function render(){H.motion?.dispose($('#view-content')||document);user=H.requireUser(role);if(!user)return;state=D.read();if(role==='bank'&&bank(user.bankId)?.status!=='active'){location.replace(url('status.html?type=denied'));return}if(view==='staff'&&user.staffType!=='representative'){location.replace(url('status.html?type=denied'));return}if(!views[view]){location.replace(url('status.html?type=missing'));return}shell();$('#view-content').innerHTML=(role==='donor'&&['dashboard','notifications','eligibility'].includes(view)?commitmentPanel():'')+views[view]();bind();H.motion?.refresh($('#view-content'));}
function perform(fn,success){try{const r=fn();render();if(success)H.toast(success);return r}catch(err){H.toast(err.message,'error')}}
function reasonModal(title,action){const el=document.createElement('div');el.className='modal modal-blur fade';el.tabIndex=-1;el.setAttribute('aria-labelledby','reason-heading');el.innerHTML=`<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="reason-form"><div class="modal-header"><h2 class="modal-title" id="reason-heading">${e(title)}</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="إغلاق"></button></div><div class="modal-body"><label class="form-label" for="reason">السبب (يُحفظ في سجل التدقيق)</label><textarea class="form-control" id="reason" name="reason" required minlength="5" maxlength="400" rows="3"></textarea><div class="text-danger small mt-2" id="reason-error" role="alert"></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">تراجع</button><button class="btn btn-danger" type="submit">تأكيد وتسجيل السبب</button></div></form></div></div>`;document.body.append(el);const modal=new tabler.Modal(el);el.addEventListener('hidden.bs.modal',()=>{modal.dispose();el.remove()},{once:true});$('#reason-form',el).onsubmit=event=>{event.preventDefault();try{action($('#reason',el).value);modal.hide();render();H.toast('تم حفظ التغيير وسجل التدقيق.')}catch(err){$('#reason-error',el).textContent=err.message}};modal.show()}
function submitForm(id,action){const form=$('#'+id);if(!form)return;form.onsubmit=async ev=>{ev.preventDefault();H.clearFormErrors(form);const btn=$('[type="submit"]',form),text=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm"></span> جارٍ الحفظ…';try{await action(Object.fromEntries(new FormData(form)));}catch(err){H.alertForm(err.message);btn.disabled=false;btn.innerHTML=text}}}
function bind(){
 if(view==='health-reports')$('#table-search')?.remove();
 $$('[data-page]').filter(b=>b.tagName==='BUTTON').forEach(b=>b.onclick=()=>{if(b.dataset.pageKey==='main')page=Number(b.dataset.page);else secondaryPages.set(b.dataset.pageKey,Number(b.dataset.page));render()});
 $('#table-sort')?.addEventListener('change',event=>{sort=event.target.value;page=1;secondaryPages.clear();render()});
 const search=$('#table-search');if(search)search.oninput=()=>{const pos=search.selectionStart;query=search.value;page=1;secondaryPages.clear();render();$('#table-search')?.focus();$('#table-search')?.setSelectionRange(pos,pos)};
 for(const [selector,key]of [['#status-filter','status'],['#bank-filter','bank'],['#date-from','from'],['#date-to','to']]){const el=$(selector);if(el)el.onchange=()=>{if(key==='status')filter=el.value;if(key==='bank')bankFilter=el.value;if(key==='from')dateFrom=el.value;if(key==='to')dateTo=el.value;page=1;secondaryPages.clear();render()}}
 $$('[data-respond]').forEach(b=>b.onclick=()=>H.confirmDialog({title:b.dataset.respond==='accepted'?'تأكيد الاستجابة للطلب؟':'الاعتذار عن الطلب؟',description:b.dataset.respond==='accepted'?'سترتبط مؤقتًا بهذا الطلب وتُخفى النداءات الأخرى حتى انتهاء التنسيق أو تراجعك. لا يُسجّل تبرع ولا تُضاف نقاط بمجرد القبول.':'سيُحفظ اعتذارك عن هذا الطلب دون تغيير التبرعات أو النقاط.',confirm:'حفظ الاستجابة',onConfirm:()=>perform(()=>D.respond(b.dataset.id,b.dataset.respond),'تم تحديث استجابتك. لا تغيير في التبرعات أو النقاط.')}));
 $$('[data-withdraw]').forEach(b=>b.onclick=()=>H.confirmDialog({title:'التراجع عن الاستجابة؟',description:'ستُحدّث استجابتك لدى المؤسسة وتظهر النداءات الأخرى المطابقة مجددًا. لا تغيير في التبرعات أو النقاط.',confirm:'تأكيد التراجع',danger:true,onConfirm:()=>perform(()=>D.respond(b.dataset.id,'withdrawn'),'تم التراجع عن الاستجابة. يمكنك استعراض النداءات الأخرى.')}));
 $$('[data-close]').forEach(b=>b.onclick=()=>reasonModal('إغلاق طلب الدم',reason=>D.closeRequest(b.dataset.id,b.dataset.close,reason)));
 $$('[data-correct]').forEach(b=>b.onclick=()=>reasonModal('تصحيح توثيق وعكس 5 نقاط',reason=>D.correctDonation(b.dataset.correct,reason)));
 $$('[data-toggle-user]').forEach(b=>b.onclick=()=>reasonModal('تغيير حالة الحساب',reason=>D.toggleUser(b.dataset.toggleUser,reason)));
 $$('[data-toggle-bank]').forEach(b=>b.onclick=()=>reasonModal('تغيير حالة المؤسسة',reason=>D.toggleBank(b.dataset.toggleBank,reason)));
 $$('[data-edit-request]').forEach(b=>b.onclick=()=>requestEditor(b.dataset.editRequest));
 $$('[data-edit-bank]').forEach(b=>b.onclick=()=>bankEditor(b.dataset.editBank));
 $$('[data-read]').forEach(a=>a.onclick=()=>D.markRead(a.dataset.read));$('[data-read-all]')?.addEventListener('click',()=>perform(()=>D.markRead(),'تم تحديد الإشعارات كمقروءة.'));
 submitForm('request-form',data=>{const r=D.createRequest(data);location.href=link('request-details','?id='+encodeURIComponent(r.id))});
 submitForm('profile-form',data=>{const verify=D.saveProfile(data);if(verify)location.href=url('verify.html');else{render();H.toast('تم حفظ بياناتك.')}});
 submitForm('staff-form',async data=>{await D.createStaff(data);render();H.toast('تم إنشاء الموظف بانتظار تفعيل البريد التجريبي عند دخوله.')} );
 submitForm('bank-form',async data=>{await D.createBank(data);render();H.toast('تم إنشاء المؤسسة وممثلها الرسمي الأول.')} );
 const city=$('#bank-form [name="city"]');if(city)city.onchange=()=>{$('#area').innerHTML=Object.keys(D.locations[city.value]||{}).map(a=>`<option value="${e(a)}">${e(a)}</option>`).join('')};
 const donorSearch=$('#donor-search');if(donorSearch)donorSearch.oninput=()=>{const q=donorSearch.value.toLowerCase();$$('#donorId option').forEach(o=>o.hidden=Boolean(o.value&&!o.textContent.toLowerCase().includes(q)))};
 submitForm('donation-form',data=>{const form=$('#donation-form'),btn=$('[type="submit"]',form);btn.disabled=false;btn.textContent='تأكيد التبرع وإضافة 5 نقاط';H.confirmDialog({title:'تأكيد تبرع مكتمل؟',description:'سيُحفظ التبرع باسمك ومؤسستك وتُضاف 5 نقاط مرة واحدة. لا تؤكد مجرد قبول أو حضور.',confirm:'تأكيد وإضافة 5 نقاط',onConfirm:()=>{try{D.recordDonation(data);location.href=link('reports','?recorded=1')}catch(err){H.alertForm(err.message)}}})});
 $('[data-print]')?.addEventListener('click',()=>window.print());$$('[data-export]').forEach(b=>b.addEventListener('click',()=>exportCSV(b.dataset.table)));
}
function exportCSV(tableId){const tableEl=tableId?document.getElementById(tableId):$('#table-main')||$('#view-content table');if(!tableEl){H.toast('لا توجد بيانات للتصدير.','info');return}const rows=[...tableEl.rows].map(r=>[...r.cells].map(c=>'"'+c.innerText.replace(/"/g,'""').replace(/^([=+@-])/,'\t$1')+'"').join(','));const blob=new Blob(['\ufeff'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`hayat-demo-${view}-${D.today()}.csv`;a.click();URL.revokeObjectURL(href);H.toast('تم تصدير الصفوف المعروضة فقط إلى CSV تجريبي.','info')}
function showSkeleton(){if(!$('#view-content')){user=H.requireUser(role);if(!user)return;state=D.read();shell();}$('#view-content').innerHTML='<div class="card loading-skeleton" role="status" aria-label="جارٍ تحميل البيانات"><div class="card-body"><span class="visually-hidden">جارٍ تحميل البيانات…</span><div class="skeleton-line w-75"></div><div class="skeleton-line"></div><div class="skeleton-line w-50"></div></div></div>';$('#view-content').setAttribute('aria-busy','true')}
function showError(error){if(!$('#app'))return;const target=$('#view-content')||$('#app');target.removeAttribute('aria-busy');target.innerHTML=empty('تعذر عرض البيانات','تعذر قراءة بيانات التجربة. أعد المحاولة، أو ارجع للصفحة الرئيسية.',`<button class="btn btn-primary" type="button" data-retry>إعادة المحاولة</button><a class="btn btn-outline-secondary" href="${url('index.html')}">الرئيسية</a>`);$('[data-retry]')?.addEventListener('click',safeRender);console.warn('Hayat demo data unavailable:',error.message)}
function safeRender(){const drawer=$('#sidebar-menu.show');if(drawer){drawer.addEventListener('hidden.bs.offcanvas',safeRender,{once:true});tabler.Offcanvas.getOrCreateInstance(drawer).hide();return}try{render();$('#view-content')?.removeAttribute('aria-busy')}catch(error){showError(error)}}
document.addEventListener('DOMContentLoaded',()=>{try{D.syncMatches();showSkeleton();requestAnimationFrame(safeRender)}catch(error){showError(error)};if(new URLSearchParams(location.search).has('recorded')){H.toast('تم توثيق التبرع وإضافة 5 نقاط مرة واحدة.');const clean=new URL(location.href);clean.searchParams.delete('recorded');window.history.replaceState(null,'',clean.pathname+clean.search+clean.hash)}});
window.addEventListener('storage',event=>{if(event.key?.startsWith(H.prefix))safeRender()});
})();
